@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');

:root {
  color-scheme: light;
  --paper: #f6f7f1;
  --ink: #203d35;
  --muted: #82918a;
  --line: #e6e9df;
  --green: #c9ef74;
  --deep-green: #274c40;
  --mono: 'DM Mono', ui-monospace, monospace;
  --sans: 'DM Sans', system-ui, sans-serif;
  --display: 'Manrope', var(--sans);
  font-family: var(--sans);
  background: var(--paper);
  color: var(--ink);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; min-height: 100svh; background: var(--paper); }
button { font: inherit; }
.page-shell { width: min(1120px, calc(100% - 64px)); margin: 0 auto; }
.topbar { height: 78px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); }
.wordmark { color: var(--ink); text-decoration: none; display: inline-flex; gap: 11px; align-items: center; font: 800 17px/1 var(--display); letter-spacing: -.8px; }
.wordmark-light { color: #84938a; font-weight: 500; }
.brand-mark { width: 27px; height: 27px; padding: 4px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 3px; border-radius: 8px; background: var(--deep-green); transform: rotate(-7deg); }
.brand-mark i { border-radius: 2px; background: var(--green); }
.brand-mark i:nth-child(2) { opacity: .63; }.brand-mark i:nth-child(3) { opacity: .42; }.brand-mark i:nth-child(4) { background: white; }
.top-note, .footer, .side-kicker, .side-bottom, .eyebrow, .stat-label, .board-foot { font-family: var(--mono); letter-spacing: 1.15px; }
.top-note { color: #89978f; font-size: 9px; display: flex; align-items: center; gap: 9px; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: #acd460; box-shadow: 0 0 0 3px #eaf2db; }
.icon-button { border: 0; background: none; color: var(--ink); display: grid; place-items: center; width: 40px; height: 40px; border-radius: 12px; cursor: pointer; }
.icon-button:hover { background: #ecefe6; }.icon-button svg { width: 19px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }.sound-on { display: none; }.sound-button.is-on .sound-on { display: block; }.sound-button.is-on .sound-off { display: none; }
.game-layout { display: grid; grid-template-columns: minmax(0, 620px) minmax(270px, 1fr); gap: 68px; align-items: stretch; padding: 41px 0 39px; }
.game-main { min-width: 0; }
.intro-row { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 23px; }
.eyebrow { display: flex; gap: 9px; align-items: center; font-size: 9px; font-weight: 500; letter-spacing: 1.15px; color: #87958d; margin-bottom: 11px; }
.eyebrow-line { display: inline-block; height: 1px; width: 17px; background: #9dc957; }
h1 { margin: 0; font: 700 clamp(38px, 4.5vw, 55px)/1.08 var(--display); letter-spacing: -3.2px; color: #23463b; }
h1 span { color: #9abe5d; }
.intro-sticker { width: 65px; height: 65px; display: flex; flex-direction: column; justify-content: center; align-items: center; background: #e9efd9; border-radius: 50%; color: #6f8e47; transform: rotate(9deg); margin: 0 5px 3px 0; }
.intro-sticker > span { font-size: 18px; line-height: 1; }.intro-sticker small { font: 500 7px/1.35 var(--mono); letter-spacing: 1px; text-align: center; margin-top: 3px; }
.game-toolbar { display: flex; justify-content: space-between; align-items: flex-end; gap: 14px; margin-bottom: 13px; }
.stats { display: flex; gap: 7px; }
.stat-card { width: 87px; height: 58px; position: relative; display: flex; flex-direction: column; justify-content: center; padding: 6px 11px 5px; border: 1px solid #e6e9df; border-radius: 9px; background: #fbfcf8; }
.score-card { width: 96px; background: #eaf0df; border-color: #eaf0df; }
.stat-label { color: #89958b; font-size: 8px; font-weight: 500; line-height: 1; margin-bottom: 5px; }
.stat-card strong { font: 700 17px/1 var(--display); letter-spacing: -.45px; font-variant-numeric: tabular-nums; color: #294a3e; }
.score-pop { position: absolute; right: 6px; top: 4px; font: 700 10px var(--display); color: #8db84d; opacity: 0; pointer-events: none; }.score-pop.show { animation: scoreUp .75s ease-out; }
@keyframes scoreUp { 0% { opacity: 0; transform: translateY(8px); } 25% { opacity: 1; transform: translateY(0); } 100% { opacity: 0; transform: translateY(-18px); } }
.actions { display: flex; gap: 7px; }
.action-button { min-height: 39px; padding: 0 12px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; border-radius: 8px; border: 1px solid #dfe4d9; color: #52675d; background: #fbfcf8; cursor: pointer; font-size: 11px; font-weight: 600; transition: background .16s, transform .16s, border-color .16s; -webkit-tap-highlight-color: transparent; }
.action-button:hover:not(:disabled) { background: white; border-color: #a9bd8f; transform: translateY(-1px); }.action-button:active:not(:disabled) { transform: scale(.97); }.action-button:disabled { opacity: .45; cursor: default; }.action-button span { font-size: 16px; line-height: 1; }
.restart-button { color: #fff; background: #315a4b; border-color: #315a4b; padding: 0 14px; }.restart-button:hover:not(:disabled) { color: #fff; background: #23463b; border-color: #23463b; }
.board-wrap { width: 100%; }
.board { --gap: clamp(7px, 1.25vw, 11px); width: 100%; aspect-ratio: 1; padding: var(--gap); position: relative; overflow: hidden; border-radius: 13px; background: #dfe7d3; touch-action: none; user-select: none; -webkit-user-select: none; outline: none; box-shadow: 0 3px 0 #d6dfc9, 0 12px 30px rgba(55, 75, 54, .055); }
.board:focus-visible { outline: 3px solid #9dbd6d; outline-offset: 3px; }
.board-grid, .tiles { position: absolute; inset: var(--gap); display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(4, 1fr); gap: var(--gap); }
.board-grid { pointer-events: none; }.board-grid span { border-radius: 8px; background: rgba(248, 250, 241, .53); }
.tiles { pointer-events: none; }
.tile { grid-row: var(--row); grid-column: var(--col); position: relative; z-index: 1; display: grid; place-items: center; border-radius: 8px; background: #f7f8f2; color: #50675b; font: 700 clamp(22px, 4.4vw, 38px)/1 var(--display); letter-spacing: -1.7px; font-variant-numeric: tabular-nums; box-shadow: 0 2px 0 rgba(43, 62, 47, .08), 0 4px 11px rgba(45, 68, 51, .06); animation: tileIn .16s cubic-bezier(.2,.8,.25,1.3) both; transition: grid-row .11s ease-out, grid-column .11s ease-out, background .15s, color .15s, transform .15s; }
.tile.tile-2 { background: #fcfcf7; color: #5c7063; }.tile.tile-4 { background: #f1f3dc; color: #61764e; }.tile.tile-8 { background: #dcebb9; color: #526a3d; }.tile.tile-16 { background: #c5df8e; color: #3e6036; }.tile.tile-32 { background: #a7cf69; color: #fff; }.tile.tile-64 { background: #82b85a; color: #fff; }.tile.tile-128 { background: #f4c778; color: #fff; font-size: clamp(19px, 3.8vw, 33px); }.tile.tile-256 { background: #efa95f; color: #fff; font-size: clamp(19px, 3.8vw, 33px); }.tile.tile-512 { background: #ec8c60; color: #fff; font-size: clamp(19px, 3.8vw, 33px); }.tile.tile-1024 { background: #d97e6a; color: #fff; font-size: clamp(15px, 3vw, 26px); letter-spacing: -1px; }.tile.tile-2048 { background: #527d62; color: #f5f8e8; font-size: clamp(15px, 3vw, 26px); letter-spacing: -1px; box-shadow: inset 0 0 0 2px rgba(245,248,232,.5), 0 3px 13px rgba(45,68,51,.18); }.tile.tile-super { background: #394f45; color: #f5f8e8; font-size: clamp(14px, 2.8vw, 24px); letter-spacing: -1px; }
.tile.merged { animation: mergePop .2s cubic-bezier(.2,.8,.25,1.4) both; z-index: 2; }
@keyframes tileIn { from { opacity: .35; transform: scale(.76); } to { opacity: 1; transform: scale(1); } }
@keyframes mergePop { 0% { transform: scale(.92); } 55% { transform: scale(1.13); } 100% { transform: scale(1); } }
.board-foot { display: flex; justify-content: space-between; align-items: center; padding: 13px 2px 0; color: #94a097; font-size: 8px; letter-spacing: .8px; }
.keyboard-key { width: 14px; height: 14px; display: inline-grid; place-items: center; border: 1px solid #d9e0d4; border-radius: 3px; margin-left: 3px; font: 9px/1 var(--sans); color: #68796e; }.keyboard-key:first-child { margin-left: 8px; }.swipe-symbol { margin-left: 4px; font-size: 12px; color: #8ca65d; }
.how-to { display: flex; align-items: center; gap: 12px; margin-top: 21px; padding: 13px 15px; border-radius: 9px; background: #eef1e7; color: #6d7f72; }.how-icon { color: #a6c76a; font-size: 16px; }.how-to p { margin: 0; font-size: 11px; line-height: 1.6; }.how-to strong { color: #3f5c4c; }.how-to b { color: #3f5c4c; }
.side-panel { min-height: 600px; position: relative; overflow: hidden; display: flex; flex-direction: column; justify-content: center; padding: 38px 35px; border-radius: 13px; background: #2b5043; color: #f5f5e9; }
.side-panel:before { content: ''; position: absolute; width: 280px; height: 280px; right: -114px; top: -102px; border: 1px solid rgba(226, 239, 202, .11); border-radius: 50%; box-shadow: 0 0 0 31px rgba(226,239,202,.025), 0 0 0 62px rgba(226,239,202,.025); }
.side-content { position: relative; z-index: 1; margin-top: -26px; }.side-kicker { color: #b6d485; font-size: 8px; letter-spacing: 1.1px; }
.side-content h2 { margin: 18px 0 13px; font: 600 38px/1.1 var(--display); letter-spacing: -2px; }.side-content > p { max-width: 230px; margin: 0; color: #c2d0c4; font-size: 12px; line-height: 1.75; }
.rule-list { margin-top: 36px; border-top: 1px solid rgba(239, 245, 227, .15); }.rule { height: 49px; display: flex; align-items: center; gap: 11px; border-bottom: 1px solid rgba(239, 245, 227, .15); font-size: 11px; color: #eef1e5; }.rule-number { font: 9px var(--mono); color: #b2d27e; }.rule-arrow { margin-left: auto; font-size: 15px; color: #b2d27e; }
.side-note { margin-top: 25px; padding: 12px 11px; border-radius: 7px; background: rgba(245,248,232,.08); color: #c5d5c2; font-size: 10px; }.side-note span { color: #c6df92; margin-right: 7px; font-size: 13px; }
.side-bottom { position: absolute; left: 35px; right: 35px; bottom: 23px; display: flex; justify-content: space-between; color: rgba(234,241,221,.42); font-size: 7px; letter-spacing: .8px; }
.side-orbit { position: absolute; color: #afcc7a; }.orbit-one { right: 35px; top: 44px; font-size: 23px; opacity: .55; }.orbit-two { right: 24px; top: 92px; font-size: 35px; opacity: .25; }
.footer { display: flex; justify-content: space-between; border-top: 1px solid var(--line); padding: 17px 0 20px; color: #a1aaa2; font-size: 8px; letter-spacing: .9px; }
.board-overlay { position: absolute; z-index: 5; inset: 0; display: grid; place-items: center; padding: 20px; background: rgba(33, 59, 49, .47); backdrop-filter: blur(4px); }.board-overlay[hidden] { display: none; }
.overlay-card { width: min(100%, 300px); padding: 26px 23px 23px; text-align: center; border-radius: 13px; background: #f7f8f1; box-shadow: 0 15px 50px rgba(20,40,30,.2); animation: tileIn .2s ease-out both; }.overlay-spark { display: grid; place-items: center; width: 38px; height: 38px; margin: 0 auto 13px; background: #e9efd9; border-radius: 50%; color: #83a74c; font-size: 20px; }.overlay-card h2 { margin: 0 0 8px; color: #274b3e; font: 700 23px var(--display); letter-spacing: -.8px; }.overlay-card p { margin: 0; color: #74837a; font-size: 12px; line-height: 1.5; }.overlay-actions { display: flex; justify-content: center; gap: 8px; margin-top: 20px; }.overlay-actions button { padding: 10px 15px; border: 0; border-radius: 7px; background: #315a4b; color: white; font-size: 11px; font-weight: 600; cursor: pointer; }.overlay-actions button.secondary { background: #e8eee0; color: #46604f; }
.toast { position: fixed; z-index: 10; left: 50%; bottom: max(20px, env(safe-area-inset-bottom)); transform: translate(-50%, 12px); padding: 10px 15px; background: #274b3e; border-radius: 8px; color: white; font-size: 12px; opacity: 0; pointer-events: none; transition: opacity .2s, transform .2s; box-shadow: 0 5px 18px rgba(30,55,43,.18); }.toast.show { opacity: 1; transform: translate(-50%, 0); }
@media (min-width: 1100px) { .game-main { max-width: 560px; }.game-layout { grid-template-columns: minmax(0, 560px) minmax(270px, 1fr); gap: 84px; justify-content: center; } }
@media (max-width: 850px) { .page-shell { width: min(620px, calc(100% - 40px)); }.game-layout { display: block; padding: 32px 0 25px; }.game-main { width: 100%; }.side-panel { display: none; }h1 { font-size: clamp(42px, 8vw, 55px); }.board { --gap: clamp(7px, 1.8vw, 11px); } }
@media (max-width: 500px) { .page-shell { width: min(440px, calc(100% - 32px)); }.topbar { height: 62px; }.top-note { font-size: 7px; letter-spacing: .65px; gap: 7px; }.brand-mark { width: 25px; height: 25px; }.wordmark { font-size: 16px; gap: 9px; }.icon-button { width: 35px; height: 35px; }.game-layout { padding-top: 24px; }.intro-row { margin-bottom: 19px; }h1 { font-size: clamp(39px, 10.1vw, 49px); letter-spacing: -2.7px; }.eyebrow { font-size: 8px; margin-bottom: 9px; }.intro-sticker { width: 54px; height: 54px; margin-bottom: 0; }.intro-sticker > span { font-size: 15px; }.intro-sticker small { font-size: 6px; }.game-toolbar { align-items: center; flex-wrap: wrap; gap: 10px; margin-bottom: 12px; }.stats { gap: 6px; }.stat-card { width: 72px; height: 53px; padding-left: 9px; }.score-card { width: 79px; }.stat-label { font-size: 7px; margin-bottom: 4px; }.stat-card strong { font-size: 16px; }.actions { margin-left: auto; gap: 6px; }.action-button { min-height: 36px; padding: 0 9px; font-size: 10px; }.restart-button { padding: 0 10px; }.board { --gap: 8px; border-radius: 11px; }.board-grid, .tiles { border-radius: 6px; }.board-grid span, .tile { border-radius: 6px; }.tile { font-size: clamp(24px, 8vw, 35px); }.tile.tile-128, .tile.tile-256, .tile.tile-512 { font-size: clamp(19px, 6vw, 28px); }.tile.tile-1024, .tile.tile-2048, .tile.tile-super { font-size: clamp(15px, 4.8vw, 23px); }.board-foot { font-size: 7px; padding-top: 11px; letter-spacing: .55px; }.keyboard-key { width: 13px; height: 13px; }.how-to { margin-top: 17px; padding: 11px 12px; }.how-to p { font-size: 10px; }.footer { font-size: 6px; letter-spacing: .5px; padding-top: 14px; }.sound-button { margin-right: -6px; } }
@media (max-width: 360px) { .page-shell { width: calc(100% - 24px); }.top-note { font-size: 6px; }.stat-card { width: 66px; padding-left: 7px; }.score-card { width: 72px; }.actions { gap: 4px; }.action-button { padding: 0 7px; }.restart-button { padding: 0 8px; }.board { --gap: 6px; }.board-foot { letter-spacing: .2px; }.keyboard-key { margin-left: 1px; }.keyboard-key:first-child { margin-left: 4px; } }
@media (max-height: 740px) and (max-width: 850px) { .game-layout { padding-top: 19px; }.intro-row { margin-bottom: 13px; }.how-to { margin-top: 12px; }.footer { padding-top: 11px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; } }

(() => {
  'use strict';

  const SIZE = 4;
  const TARGET = 2048;
  const SAVE_KEY = 'slideclub-game-v1';
  const BEST_KEY = 'slideclub-best-v1';
  const SOUND_KEY = 'slideclub-sound-v1';
  const boardEl = document.getElementById('board');
  const tilesEl = document.getElementById('tiles');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');
  const timeEl = document.getElementById('time');
  const undoButton = document.getElementById('undo-button');
  const restartButton = document.getElementById('restart-button');
  const overlay = document.getElementById('board-overlay');
  const toast = document.getElementById('toast');
  const soundButton = document.getElementById('sound-toggle');
  const scorePop = document.getElementById('score-pop');
  let nextId = 1;
  let undoState = null;
  let toastTimer;
  let audioContext;
  let soundOn = localStorage.getItem(SOUND_KEY) === 'on';
  let pointerStart = null;
  let state = freshState();
  let best = Number(localStorage.getItem(BEST_KEY)) || 0;

  function freshState() {
    return { board: Array(SIZE * SIZE).fill(null), score: 0, elapsed: 0, startedAt: null, won: false, over: false, continued: false };
  }
  function copyBoard(board) { return board.map(tile => tile ? { ...tile } : null); }
  function elapsedNow() { return state.elapsed + (state.startedAt ? Date.now() - state.startedAt : 0); }
  function formatTime(ms) {
    const total = Math.floor(ms / 1000);
    const mins = Math.floor(total / 60);
    const secs = total % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  }
  function save() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify({ board: state.board, score: state.score, elapsed: elapsedNow(), won: state.won, over: state.over, continued: state.continued, nextId }));
      localStorage.setItem(BEST_KEY, String(best));
    } catch (_) { /* Private browsing can disable storage; the game still works. */ }
  }
  function load() {
    try {
      const saved = JSON.parse(localStorage.getItem(SAVE_KEY));
      if (!saved || !Array.isArray(saved.board) || saved.board.length !== SIZE * SIZE) return false;
      if (!saved.board.every(tile => tile === null || (Number.isInteger(tile.val) && tile.val >= 2 && Number.isInteger(tile.id)))) return false;
      state = { board: saved.board, score: Number(saved.score) || 0, elapsed: Number(saved.elapsed) || 0, startedAt: null, won: Boolean(saved.won), over: Boolean(saved.over), continued: Boolean(saved.continued) };
      nextId = Math.max(Number(saved.nextId) || 1, ...state.board.filter(Boolean).map(tile => tile.id + 1));
      return true;
    } catch (_) { return false; }
  }
  function randomEmpty() {
    const empty = [];
    state.board.forEach((tile, i) => { if (!tile) empty.push(i); });
    if (!empty.length) return false;
    const index = empty[Math.floor(Math.random() * empty.length)];
    state.board[index] = { id: nextId++, val: Math.random() < 0.9 ? 2 : 4 };
    return true;
  }
  function initGame() {
    state = freshState();
    undoState = null;
    randomEmpty(); randomEmpty();
    hideOverlay();
    render();
    save();
    boardEl.focus({ preventScroll: true });
  }
  function showToast(message) {
    toast.textContent = message;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('show'), 1700);
  }
  function tick() {
    timeEl.textContent = formatTime(elapsedNow());
    if (state.startedAt) save();
  }
  function render() {
    const existing = new Map([...tilesEl.children].map(element => [Number(element.dataset.id), element]));
    const present = new Set();
    state.board.forEach((tile, index) => {
      if (!tile) return;
      present.add(tile.id);
      let element = existing.get(tile.id);
      const isNew = !element;
      if (!element) {
        element = document.createElement('div');
        element.className = 'tile';
        element.dataset.id = String(tile.id);
        element.setAttribute('role', 'presentation');
        tilesEl.appendChild(element);
      }
      const row = Math.floor(index / SIZE);
      const col = index % SIZE;
      element.style.setProperty('--row', row);
      element.style.setProperty('--col', col);
      element.style.transform = `translate3d(calc(var(--col) * (100% + var(--gap))), calc(var(--row) * (100% + var(--gap))), 0)`;
      element.textContent = String(tile.val);
      element.className = `tile ${tile.val <= 2048 ? `tile-${tile.val}` : 'tile-super'}${tile.justMerged ? ' merged' : ''}`;
      if (isNew) element.style.animationDelay = `${Math.random() * 45}ms`;
      delete tile.justMerged;
    });
    for (const [id, element] of existing) if (!present.has(id)) element.remove();
    scoreEl.textContent = state.score.toLocaleString();
    bestEl.textContent = best.toLocaleString();
    timeEl.textContent = formatTime(elapsedNow());
    undoButton.disabled = !undoState;
    boardEl.setAttribute('aria-label', `2048 game board. Score ${state.score}. Use arrow keys or swipe to move tiles.`);
    if (state.over) showEndOverlay();
    else if (state.won && !state.continued) showWinOverlay();
  }
  function playSound(merged = false) {
    if (!soundOn) return;
    try {
      audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
      const osc = audioContext.createOscillator();
      const gain = audioContext.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(merged ? 520 : 300, audioContext.currentTime);
      if (merged) osc.frequency.exponentialRampToValueAtTime(760, audioContext.currentTime + .08);
      gain.gain.setValueAtTime(.035, audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + .11);
      osc.connect(gain); gain.connect(audioContext.destination);
      osc.start(); osc.stop(audioContext.currentTime + .12);
    } catch (_) { /* Audio is an optional flourish. */ }
  }
  function flashScore(points) {
    if (!points) return;
    scorePop.textContent = `+${points}`;
    scorePop.classList.remove('show');
    void scorePop.offsetWidth;
    scorePop.classList.add('show');
  }

  function indicesFor(direction, line) {
    const indices = [];
    for (let step = 0; step < SIZE; step++) {
      if (direction === 'left') indices.push(line * SIZE + step);
      if (direction === 'right') indices.push(line * SIZE + (SIZE - 1 - step));
      if (direction === 'up') indices.push(step * SIZE + line);
      if (direction === 'down') indices.push((SIZE - 1 - step) * SIZE + line);
    }
    return indices;
  }
  function canMove() {
    if (state.board.some(tile => !tile)) return true;
    for (let row = 0; row < SIZE; row++) for (let col = 0; col < SIZE; col++) {
      const value = state.board[row * SIZE + col].val;
      if (col < SIZE - 1 && value === state.board[row * SIZE + col + 1].val) return true;
      if (row < SIZE - 1 && value === state.board[(row + 1) * SIZE + col].val) return true;
    }
    return false;
  }
  function move(direction) {
    if (state.over || (state.won && !state.continued)) return;
    const before = copyBoard(state.board);
    const previousScore = state.score;
    let gained = 0;
    let didMove = false;
    for (let line = 0; line < SIZE; line++) {
      const indices = indicesFor(direction, line);
      const original = indices.map(index => state.board[index]).filter(Boolean);
      const compacted = [];
      for (let i = 0; i < original.length; i++) {
        if (i + 1 < original.length && original[i].val === original[i + 1].val) {
          const val = original[i].val * 2;
          compacted.push({ id: nextId++, val, justMerged: true });
          gained += val;
          i++;
        } else compacted.push(original[i]);
      }
      const result = [...compacted, ...Array(SIZE - compacted.length).fill(null)];
      indices.forEach((index, i) => {
        const previous = state.board[index];
        const next = result[i];
        if ((previous?.id ?? null) !== (next?.id ?? null)) didMove = true;
        state.board[index] = next;
      });
    }
    if (!didMove) return;
    undoState = { board: before, score: previousScore };
    if (!state.startedAt) state.startedAt = Date.now();
    state.score += gained;
    const made2048 = state.board.some(tile => tile?.val >= TARGET);
    randomEmpty();
    if (made2048 && !state.won) state.won = true;
    if (!canMove()) state.over = true;
    render();
    flashScore(gained);
    playSound(gained > 0);
    save();
    if (state.over) showEndOverlay();
    else if (made2048 && !state.continued) showWinOverlay();
  }
  function undo() {
    if (!undoState) return;
    state.board = copyBoard(undoState.board);
    state.score = undoState.score;
    state.over = false;
    if (state.won && !state.board.some(tile => tile?.val >= TARGET)) state.won = false;
    undoState = null;
    hideOverlay();
    render(); save();
    showToast('One move rewound. Your time keeps flowing.');
  }
  function makeButton(text, handler, secondary = false) {
    const button = document.createElement('button');
    button.type = 'button'; button.textContent = text;
    if (secondary) button.className = 'secondary';
    button.addEventListener('click', handler);
    return button;
  }
  function setOverlay(title, message, buttons) {
    document.getElementById('overlay-title').textContent = title;
    document.getElementById('overlay-message').textContent = message;
    const actions = document.getElementById('overlay-actions');
    actions.replaceChildren(...buttons);
    overlay.hidden = false;
  }
  function hideOverlay() { overlay.hidden = true; }
  function showWinOverlay() {
    setOverlay('You made 2048!', 'A lovely bit of focus. Want to see how far you can go?', [
      makeButton('Keep going', () => { state.continued = true; hideOverlay(); render(); save(); }),
      makeButton('New game', initGame, true)
    ]);
  }
  function showEndOverlay() {
    setOverlay('No more moves.', `You scored ${state.score.toLocaleString()} in ${formatTime(elapsedNow())}. Fancy another go?`, [
      makeButton('Play again', initGame),
      makeButton('Undo last', undo, true)
    ]);
  }
  function showRestartPrompt() {
    if (state.score === 0 && !state.startedAt) { initGame(); return; }
    setOverlay('A fresh start?', 'This game is going rather nicely. Are you sure you want to begin again?', [
      makeButton('Start fresh', initGame),
      makeButton('Keep playing', () => { hideOverlay(); boardEl.focus({ preventScroll: true }); }, true)
    ]);
  }

  boardEl.addEventListener('keydown', event => {
    const directions = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };
    if (directions[event.key]) { event.preventDefault(); move(directions[event.key]); }
  });
  boardEl.addEventListener('pointerdown', event => {
    if (event.button !== undefined && event.button !== 0) return;
    boardEl.focus({ preventScroll: true });
    const rect = boardEl.getBoundingClientRect();
    const gap = parseFloat(getComputedStyle(boardEl).getPropertyValue('--gap')) || 8;
    const inner = rect.width - gap * 2;
    const cell = (inner - gap * 3) / 4;
    const x = event.clientX - rect.left - gap;
    const y = event.clientY - rect.top - gap;
    pointerStart = { x: event.clientX, y: event.clientY, row: Math.floor(y / (cell + gap)), col: Math.floor(x / (cell + gap)) };
    if (boardEl.setPointerCapture && event.pointerId !== undefined) boardEl.setPointerCapture(event.pointerId);
  });
  boardEl.addEventListener('pointerup', event => {
    if (!pointerStart) return;
    const dx = event.clientX - pointerStart.x;
    const dy = event.clientY - pointerStart.y;
    const threshold = Math.max(20, boardEl.clientWidth * .055);
    if (Math.max(Math.abs(dx), Math.abs(dy)) > threshold) {
      move(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up'));
    } else {
      const { row, col } = pointerStart;
      if (row >= 0 && row < SIZE && col >= 0 && col < SIZE) tapCell(row, col);
    }
    pointerStart = null;
  });
  boardEl.addEventListener('pointercancel', () => { pointerStart = null; });
  function tapCell(row, col) {
    const index = row * SIZE + col;
    if (state.board[index]) {
      const choices = [[row - 1, col, 'down'], [row + 1, col, 'up'], [row, col - 1, 'right'], [row, col + 1, 'left']];
      for (const [r, c, direction] of choices) if (r >= 0 && r < SIZE && c >= 0 && c < SIZE && !state.board[r * SIZE + c]) { move(direction); return; }
    } else {
      const choices = [[row - 1, col, 'down'], [row + 1, col, 'up'], [row, col - 1, 'right'], [row, col + 1, 'left']];
      for (const [r, c, direction] of choices) if (r >= 0 && r < SIZE && c >= 0 && c < SIZE && state.board[r * SIZE + c]) { move(direction); return; }
    }
  }
  undoButton.addEventListener('click', undo);
  restartButton.addEventListener('click', showRestartPrompt);
  soundButton.addEventListener('click', () => {
    soundOn = !soundOn;
    soundButton.classList.toggle('is-on', soundOn);
    soundButton.setAttribute('aria-label', soundOn ? 'Turn sound off' : 'Turn sound on');
    soundButton.title = soundOn ? 'Sound on' : 'Sound off';
    try { localStorage.setItem(SOUND_KEY, soundOn ? 'on' : 'off'); } catch (_) {}
    if (soundOn) playSound(false);
  });
  window.addEventListener('keydown', event => {
    if (event.key === 'Escape' && !overlay.hidden) hideOverlay();
    if (event.key.toLowerCase() === 'u' && !event.ctrlKey && !event.metaKey && !event.altKey && overlay.hidden) undo();
  });
  window.addEventListener('beforeunload', save);
  setInterval(tick, 1000);

  if (!load()) { randomEmpty(); randomEmpty(); }
  soundButton.classList.toggle('is-on', soundOn);
  soundButton.setAttribute('aria-label', soundOn ? 'Turn sound off' : 'Turn sound on');
  soundButton.title = soundOn ? 'Sound on' : 'Sound off';
  if (state.over) showEndOverlay();
  else if (state.won && !state.continued) showWinOverlay();
  render();
  save();
})();

